<div class="ss-form" id="expenseForm">

  <h2>Expense Details</h2>

  <label>Select Group</label>
  <select id="groupSelect">
    <option value="">Choose a group</option>
    <option value="goa">Goa Trip</option>
    <option value="flat">Flat Expenses</option>
    <option value="college">College Friends</option>
  </select>

  <label>Expense Name</label>
  <input type="text" id="expenseTitle" placeholder="e.g. Dinner">

  <label>Amount (₹)</label>
  <input type="number" id="expenseAmount" placeholder="Enter amount" min="0.01" step="0.01">

  <label>Category</label>
  <select id="expenseCategory">
    <option value="">Select category</option>
    <option>Food</option>
    <option>Travel</option>
    <option>Shopping</option>
    <option>Groceries</option>
    <option>Entertainment</option>
    <option>Other</option>
  </select>

  <label>Paid By</label>
  <select id="paidBy">
    <option value="">Select member</option>
  </select>

  <label>Date</label>
  <input type="date" id="expenseDate">

  <label>Split Type</label>
  <select id="splitType">
    <option value="equal">Equal Split</option>
    <option value="unequal">Unequal Split</option>
  </select>

  <div class="ss-divider"></div>

  <h3>Split Expense Between</h3>
  <p class="ss-help">Select or deselect members who participated in this expense.</p>

  <div id="includedMembers">
    <p class="ss-help">Select a group first.</p>
  </div>

  <div class="ss-divider"></div>

  <h3>Expense Breakdown</h3>

  <div id="splitMembers">
    <p class="ss-help">Your expense breakdown will appear here.</p>
  </div>

  <p id="expenseMessage" role="status"></p>

  <button type="button" id="saveExpense">
    Save Expense
  </button>

</div>

<style>
#expenseForm.ss-form {
  max-width: 650px;
  margin: 20px auto;
  padding: 25px;
  background: #ffffff;
  border-radius: 15px;
  box-shadow: 0 4px 18px rgba(0,0,0,0.07);
  font-family: Arial, sans-serif;
  color: #333;
}

#expenseForm h2,
#expenseForm h3 {
  color: #49318c;
}

#expenseForm h2 {
  margin-top: 0;
  margin-bottom: 22px;
}

#expenseForm h3 {
  margin-bottom: 8px;
}

#expenseForm > label {
  display: block;
  font-weight: 600;
  margin: 15px 0 7px;
}

#expenseForm input:not([type="checkbox"]),
#expenseForm select {
  width: 100%;
  padding: 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-size: 14px;
  box-sizing: border-box;
  background: #fff;
}

#expenseForm input:focus,
#expenseForm select:focus {
  outline: none;
  border-color: #7552c7;
}

#expenseForm .ss-help {
  color: #777;
  font-size: 13px;
  margin: 5px 0 12px;
}

#expenseForm .ss-divider {
  border-top: 1px solid #eee;
  margin: 22px 0;
}

#expenseForm .ss-member {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  margin: 7px 0;
  background: #f8f6fc;
  border-radius: 8px;
  cursor: pointer;
}

#expenseForm .ss-member input[type="checkbox"] {
  appearance: auto !important;
  -webkit-appearance: checkbox !important;
  display: inline-block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: static !important;
  pointer-events: auto !important;
  width: 18px !important;
  height: 18px !important;
  margin: 0 !important;
  flex-shrink: 0;
  accent-color: #7552c7;
  cursor: pointer;
}

#expenseForm .ss-member span {
  flex: 1;
  cursor: pointer;
  font-size: 14px;
}

#expenseForm .ss-split-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid #eee;
}

#expenseForm .ss-split-row input {
  max-width: 130px;
}

#expenseForm .ss-total {
  display: flex;
  justify-content: space-between;
  font-weight: bold;
  margin-top: 15px;
  color: #49318c;
}

#expenseForm #expenseMessage {
  font-size: 14px;
  margin-top: 15px;
}

#expenseForm #saveExpense {
  width: 100%;
  padding: 14px;
  margin-top: 15px;
  background: #6941c6;
  color: white;
  border: none;
  border-radius: 9px;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
}

#expenseForm #saveExpense:hover {
  background: #5230a5;
}
</style>

<script>
(function () {

  const form = document.getElementById("expenseForm");

  if (!form || form.dataset.initialized === "true") return;
  form.dataset.initialized = "true";

  const members = {
    goa: ["You", "Riya", "Ananya", "Simran"],
    flat: ["You", "Riya", "Ananya"],
    college: ["You", "Riya", "Ananya", "Simran", "Aditi"]
  };

  const groupSelect = form.querySelector("#groupSelect");
  const paidBy = form.querySelector("#paidBy");
  const includedMembers = form.querySelector("#includedMembers");
  const splitMembers = form.querySelector("#splitMembers");
  const amountInput = form.querySelector("#expenseAmount");
  const splitType = form.querySelector("#splitType");
  const message = form.querySelector("#expenseMessage");

  let selectedMembers = [];

  function getAmount() {
    return Math.round((Number(amountInput.value) || 0) * 100);
  }

  function formatMoney(paise) {
    return "₹" + (paise / 100).toFixed(2);
  }

  function populateGroup() {

    const group = groupSelect.value;
    const groupMembers = members[group] || [];

    paidBy.innerHTML = '<option value="">Select member</option>';

    groupMembers.forEach(function (member) {
      const option = document.createElement("option");
      option.value = member;
      option.textContent = member;
      paidBy.appendChild(option);
    });

    selectedMembers = [...groupMembers];

    renderIncludedMembers();
    renderSplit();

    message.textContent = "";
  }

  function renderIncludedMembers() {

    includedMembers.innerHTML = "";

    if (!groupSelect.value) {
      includedMembers.textContent = "Select a group first.";
      return;
    }

    members[groupSelect.value].forEach(function (member) {

      const row = document.createElement("div");
      row.className = "ss-member";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.value = member;
      checkbox.checked = selectedMembers.includes(member);
      checkbox.id = "ss_member_" + member.replace(/\W/g, "_");

      const name = document.createElement("span");
      name.textContent = member;

      row.appendChild(checkbox);
      row.appendChild(name);

      includedMembers.appendChild(row);

    });
  }

  includedMembers.addEventListener("change", function (e) {

    if (e.target.type !== "checkbox") return;

    const member = e.target.value;

    if (e.target.checked) {

      if (!selectedMembers.includes(member)) {
        selectedMembers.push(member);
      }

    } else {

      selectedMembers = selectedMembers.filter(function (m) {
        return m !== member;
      });

    }

    renderSplit();
    message.textContent = "";

  });

  function renderSplit() {

    splitMembers.innerHTML = "";

    const amount = getAmount();

    if (selectedMembers.length === 0) {
      splitMembers.textContent = "Please select at least one member.";
      return;
    }

    if (splitType.value === "equal") {

      const baseShare = Math.floor(amount / selectedMembers.length);
      const remainder = amount % selectedMembers.length;

      selectedMembers.forEach(function (member, index) {

        const share = baseShare + (index < remainder ? 1 : 0);

        const row = document.createElement("div");
        row.className = "ss-split-row";

        const name = document.createElement("span");
        name.textContent = member;

        const value = document.createElement("strong");
        value.textContent = formatMoney(share);

        row.appendChild(name);
        row.appendChild(value);

        splitMembers.appendChild(row);

      });

      const total = document.createElement("div");
      total.className = "ss-total";

      const totalLabel = document.createElement("span");
      totalLabel.textContent = "Total";

      const totalValue = document.createElement("span");
      totalValue.textContent = formatMoney(amount);

      total.appendChild(totalLabel);
      total.appendChild(totalValue);

      splitMembers.appendChild(total);

    } else {

      selectedMembers.forEach(function (member) {

        const row = document.createElement("div");
        row.className = "ss-split-row";

        const name = document.createElement("span");
        name.textContent = member;

        const input = document.createElement("input");
        input.type = "number";
        input.min = "0";
        input.step = "0.01";
        input.placeholder = "Enter share";
        input.dataset.member = member;

        row.appendChild(name);
        row.appendChild(input);

        splitMembers.appendChild(row);

      });

      const total = document.createElement("div");
      total.className = "ss-total";
      total.textContent = "Enter individual shares";

      splitMembers.appendChild(total);

    }
  }

  groupSelect.addEventListener("change", populateGroup);

  amountInput.addEventListener("input", renderSplit);

  splitType.addEventListener("change", renderSplit);

  form.querySelector("#saveExpense").addEventListener("click", function () {

    message.textContent = "";
    message.style.color = "#dc2626";

    const group = groupSelect.value;
    const title = form.querySelector("#expenseTitle").value.trim();
    const amount = getAmount();
    const category = form.querySelector("#expenseCategory").value;
    const payer = paidBy.value;
    const date = form.querySelector("#expenseDate").value;
    const type = splitType.value;

    if (!group || !title || !amount || !category || !payer || !date) {
      message.textContent = "Please fill in all required fields.";
      return;
    }

    if (selectedMembers.length === 0) {
      message.textContent = "Please select at least one member.";
      return;
    }

    if (!selectedMembers.includes(payer)) {
      message.textContent = "The person who paid must be included in the expense split.";
      return;
    }

    let shares = {};

    if (type === "equal") {

      const baseShare = Math.floor(amount / selectedMembers.length);
      const remainder = amount % selectedMembers.length;

      selectedMembers.forEach(function (member, index) {
        shares[member] = baseShare + (index < remainder ? 1 : 0);
      });

    } else {

      const inputs = splitMembers.querySelectorAll("input");
      let totalShares = 0;

      for (const input of inputs) {

        if (input.value.trim() === "" || !Number.isFinite(Number(input.value)) || Number(input.value) < 0) {
          message.textContent = "Enter a valid share for every selected member.";
          return;
        }

        const share = Math.round(Number(input.value) * 100);

        shares[input.dataset.member] = share;
        totalShares += share;

      }

      if (totalShares !== amount) {
        message.textContent = "Individual shares must add up to " + formatMoney(amount) + ".";
        return;
      }

    }

    const expense = {
      groupId: group,
      expenseName: title,
      amount: amount / 100,
      category: category,
      paidBy: payer,
      date: date,
      splitType: type,
      includedMembers: [...selectedMembers],
      shares: shares
    };

    console.log("Expense ready for Firebase:", expense);

    message.style.color = "#15803d";
    message.textContent = "Expense validated successfully! Firebase connection is pending.";

  });

})();
</script>
