<style>

#ss-open {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 99998;
  background: #8065C9;
  color: white;
  border: none;
  border-radius: 8px;
  padding: 12px 16px;
  font-size: 23px;
  cursor: pointer;
}

#ss-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 99998;
  display: none;
}

#ss-sidebar {
  position: fixed;
  top: 0;
  left: -280px;
  width: 260px;
  height: 100vh;
  background: #8065C9;
  z-index: 99999;
  padding: 25px 18px;
  box-sizing: border-box;
  transition: left 0.3s ease;
}

#ss-sidebar.ss-active {
  left: 0;
}

#ss-overlay.ss-active {
  display: block;
}

.ss-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: white;
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 40px;
}

#ss-close {
  background: transparent;
  border: none;
  color: white;
  font-size: 30px;
  cursor: pointer;
}

.ss-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ss-links a {
  display: flex;
  align-items: center;
  gap: 12px;
  color: white;
  text-decoration: none;
  padding: 14px 12px;
  border-radius: 8px;
  font-size: 16px;
  transition: background 0.2s;
}

.ss-links a span {
  font-size: 21px;
}

.ss-links a:hover {
  background: #6D50B5;
}

body.ss-menu-open {
  overflow: hidden;
}

</style>

<script>

(function() {

  const sidebar = document.getElementById('ss-sidebar');
  const overlay = document.getElementById('ss-overlay');
  const openBtn = document.getElementById('ss-open');
  const closeBtn = document.getElementById('ss-close');

  if (!sidebar || !overlay || !openBtn || !closeBtn) return;

  function openMenu() {
    sidebar.classList.add('ss-active');
    overlay.classList.add('ss-active');
    document.body.classList.add('ss-menu-open');
  }

  function closeMenu() {
    sidebar.classList.remove('ss-active');
    overlay.classList.remove('ss-active');
    document.body.classList.remove('ss-menu-open');
  }

  openBtn.addEventListener('click', openMenu);
  closeBtn.addEventListener('click', closeMenu);
  overlay.addEventListener('click', closeMenu);

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      closeMenu();
    }
  });

})();

</script>

