<div class="ss-history">

  <div class="ss-history-filters">
    <button class="ss-filter active" data-filter="all">All</button>
    <button class="ss-filter" data-filter="expense">Expenses</button>
    <button class="ss-filter" data-filter="settlement">Settlements</button>
  </div>

  <div class="ss-history-search">
    <span>⌕</span>
    <input type="text" id="ssHistorySearch" placeholder="Search expenses...">
  </div>

  <div class="ss-table-wrap">
    <table class="ss-table">
      <thead>
        <tr>
          <th>Date</th>
          <th>Description</th>
          <th>Group</th>
          <th>Type</th>
          <th>Amount</th>
        </tr>
      </thead>
      <tbody id="historyRows">
        <tr>
          <td colspan="5" class="ss-history-empty">
            No transactions found.
          </td>
        </tr>
      </tbody>
    </table>
  </div>

</div>

<style>
.ss-history {
  width: 100%;
  font-family: inherit;
}

.ss-history-filters {
  display: flex;
  gap: 12px;
  margin-bottom: 22px;
  flex-wrap: wrap;
}

.ss-filter {
  padding: 10px 22px;
  border: 1px solid #e5e7eb;
  border-radius: 9px;
  background: white;
  color: #555;
  cursor: pointer;
  font-size: 14px;
}

.ss-filter.active {
  background: #245c4f;
  color: white;
  border-color: #245c4f;
}

.ss-history-search {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  margin-bottom: 22px;
  background: white;
}

.ss-history-search span {
  font-size: 21px;
  color: #888;
}

.ss-history-search input {
  width: 100%;
  border: none;
  outline: none;
  background: transparent;
  font-size: 14px;
}

.ss-table-wrap {
  width: 100%;
  overflow-x: auto;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}

.ss-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 650px;
}

.ss-table th {
  background: #f7f9f8;
  color: #555;
  text-align: left;
  padding: 16px;
  font-size: 13px;
  font-weight: 600;
}

.ss-table td {
  padding: 17px 16px;
  border-top: 1px solid #eeeeee;
  font-size: 14px;
  color: #444;
}

.ss-table tbody tr:hover {
  background: #fafcfb;
}

.ss-type {
  display: inline-block;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 12px;
}

.ss-type.expense {
  background: #fff1e8;
  color: #c46a35;
}

.ss-type.settlement {
  background: #e8f5ef;
  color: #27805c;
}

.ss-history-empty {
  text-align: center;
  padding: 35px !important;
  color: #888 !important;
}

@media(max-width:600px) {
  .ss-filter {
    padding: 9px 15px;
  }
}
</style>

<script>
(function() {

  let historyData = [];
  let activeFilter = "all";

  const rows = document.getElementById("historyRows");
  const search = document.getElementById("ssHistorySearch");
  const buttons = document.querySelectorAll(".ss-filter");

  function renderHistory() {

    const searchText = search.value.toLowerCase();

    const filtered = historyData.filter(item => {

      const matchesType =
        activeFilter === "all" ||
        item.type === activeFilter;

      const matchesSearch =
        (item.description + " " + item.groupName)
        .toLowerCase()
        .includes(searchText);

      return matchesType && matchesSearch;
    });

    if (filtered.length === 0) {
      rows.innerHTML = `
        <tr>
          <td colspan="5" class="ss-history-empty">
            No transactions found.
          </td>
        </tr>`;
      return;
    }

    rows.innerHTML = filtered.map(item => {

      const date = item.date instanceof Date
        ? item.date.toLocaleDateString("en-IN")
        : item.date || "—";

      return `
        <tr>
          <td>${escapeHTML(String(date))}</td>
          <td>${escapeHTML(item.description)}</td>
          <td>${escapeHTML(item.groupName)}</td>
          <td>
            <span class="ss-type ${item.type}">
              ${item.type === "expense" ? "Expense" : "Settlement"}
            </span>
          </td>
          <td>₹${Number(item.amount).toLocaleString("en-IN")}</td>
        </tr>
      `;
    }).join("");
  }

  function escapeHTML(value) {
    return value.replace(/[&<>"']/g, char => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;"
    })[char]);
  }

  buttons.forEach(button => {
    button.addEventListener("click", function() {

      buttons.forEach(btn => btn.classList.remove("active"));

      this.classList.add("active");

      activeFilter = this.dataset.filter;

      renderHistory();
    });
  });

  search.addEventListener("input", renderHistory);

  // Called when actual history is retrieved from Firebase.
  window.loadSplitSmartHistory = function(records) {
    historyData = records;
    renderHistory();
  };

})();
</script>
